export interface WriteAccepted {
  batchId: string;
  resource: "availability" | "rates" | "restrictions";
  /** distinct cells after per-request coalescing (last write wins) */
  requestedCells: number;
  /** cells that differed from our record and were written; they will be pushed */
  acceptedCells: number;
  /** cells that already held the requested value; nothing written, nothing pushed */
  noopCells: number;
  /** groups our record refused (e.g. a plan whose policy forbids exceptions) */
  rejected: Array<{
    cells: number;
    error: string;
  }>;
  pushedBy: "inventory-drain" | "ari-projector";
  /** GET path to watch this batch land */
  poll: string;
  /** Accepted, but worth a look: an availability above the room type's room count (an oversell the channels will sell). Absent when there is nothing to say */
  warnings?: Array<{
    roomTypeId: number;
    /** Rooms of this type in our record */
    units: number;
    /** The highest count this request set for it */
    requested: number;
    message: string;
  }>;
  /** Accepted, but far outside the plan's standing price, on a property whose price band only warns (§6.6). At most 20; absent when there is nothing to say */
  priceWarnings?: Array<{
    ratePlanId: number;
    /** Hotel-local calendar date, YYYY-MM-DD */
    date: string;
    /** The price this request set, in hundredths of the major unit */
    rateMinor: number;
    /** The plan's standing price, in hundredths of the major unit */
    standingMinor: number;
    /** The same price in major units, as a decimal string ("4500.50") */
    rate?: string;
    /** The plan's standing price in major units, as a decimal string */
    standing?: string;
    message: string;
  }>;
  /** Prices this request sent that could not be kept exactly as sent, each with what was kept and why (§2.10): more decimals than the currency has, or a fraction in a currency that has none. At most 20; absent when every price was kept as sent */
  rounded?: Array<{
    /** Where in the request the amount sat, for example "updates[3].rate" */
    field: string;
    /** The amount as it was sent */
    sent: string;
    /** The amount as it is kept, in major units with the currency's own decimals */
    kept: string;
    /** Why, in a sentence; may change, do not branch on it */
    reason: string;
  }>;
  /** How many of the request's prices were rounded in all; present with rounded */
  roundedCount?: number;
  /** true when the write was taken through the safety lane: the integration is paused or over a budget, and this write only closed inventory (§6.6) */
  lane?: boolean;
  /** true on PUT /rates and PUT /restrictions for a hotel that is not live yet (§2.15): the values are in our record and are pushed when the hotel goes live (POST /go-live), not before. Absent on a live hotel, and on PUT /availability: a room count is sent at once, live or not */
  heldUntilGoLive?: boolean;
  /** What this write did not do, or will not go on doing, one plain sentence each with a stable code and what to do (§2.20). Warnings first. At most 20; absent when there is nothing to say */
  notices?: Array<{
    /** Stable: branch on it. A code you do not know is a notice added later; show its message */
    code: "NOT_SOURCE_OF_TRUTH" | "ROOM_TYPE_NOT_LINKED" | "PLAN_NOT_LINKED" | "PLAN_NOT_MAPPED" | "ROOM_STILL_ON_SALE" | "OTA_LINKED_RATES_NOT_REACHED" | "STAY_RULES_FROM_ANOTHER_PLAN" | "PER_OTA_PLANS_FOLLOW" | "PER_OTA_PLAN_FOLLOWS_PARENT" | "VALUE_HELD" | "COUNT_WAS_REFUSED" | "COUNT_ZERO_IS_NOT_STOP_SELL" | "STOP_SELL_IS_NOT_A_COUNT" | "COUNT_OPEN_BUT_PLANS_STOPPED" | "NEW_DATES_OPEN_CLOSED" | "FAR_NIGHTS_NEED_A_COUNT" | "ENGINE_WILL_REPRICE" | "ENGINE_WILL_RECOUNT" | "DRIFT_REPAIR_OFF";
    /** warning: our record shows what you sent does not do the whole job (something still sells, nothing is sent, a rule will undo it) · info: how it works, said so the next surprise is not one */
    level: "warning" | "info";
    /** What is going on, in a sentence a person can read; may change, do not branch on it */
    message: string;
    /** What to do about it, naming the call */
    action: string;
    /** The room type it is about */
    roomTypeId?: number;
    /** The rate plans it is about (the ones you wrote) */
    ratePlanIds?: Array<number>;
    /** Other plans it names: the ones still selling, the plan that carries the star, the per-OTA plans */
    otherRatePlanIds?: Array<number>;
    /** The connected channels it is about */
    channels?: Array<{
      channelId: string;
      /** BookingCom, Expedia, Agoda, Goibibo, AirBNB, … */
      kind: string;
    }>;
    /** The first night it is about */
    dateFrom?: string;
    /** The last night it is about */
    dateTo?: string;
    /** How many nights between dateFrom and dateTo it is about (they need not be consecutive) */
    nights?: number;
  }>;
  /** How many more notices there were past the 20 listed; present only when some were left out */
  noticesOmitted?: number;
}

export interface BatchStatus {
  batchId: string;
  resource: "availability" | "rates" | "restrictions";
  createdAt: string;
  requestedCells: number;
  acceptedCells: number;
  noopCells: number;
  rejected: Array<{
    cells: number;
    error: string;
  }>;
  status: "landed" | "pending" | "failed";
  pendingCells: number;
  /** Cells of this batch the channel manager refused: held, not re-sent (§6.6). More than 0 reads failed */
  parkedCells: number;
  lastError: string | null;
  /** Cells written to our record that reach no channel, by room type or rate plan. Not-linked cells are not counted as pending (they are sent nowhere); not-mapped ones are sent and counted like any other */
  unreachable?: Array<{
    /** The room type, on an availability batch */
    roomTypeId?: number;
    /** The rate plan, on a rates or restrictions batch */
    ratePlanId?: number;
    /** How many of the batch's cells are this room type's or plan's */
    cells: number;
    /** not-linked: the room type or plan has no link to the channel manager, so nothing was sent for it (GET /catalog shows its sync state); the batch reads failed. not-mapped: linked and sent, but no connected channel that is switched on sells the plan, by what was last read of the hotel's connections (nightly): nothing sells or stops because of it. A not-mapped plan does not fail the batch */
    status: "not-linked" | "not-mapped";
    message: string;
  }>;
}

export interface SyncStatus {
  propertyId: number;
  /** true on a sandbox property (a zsk_test_ key): pushes land in our record and stop there, so IN_SYNC means recorded */
  sandbox: boolean;
  /** false = nothing is pushed; ask ZimmerStack support */
  ariAuthoritative: boolean;
  inventory: {
    state: "IN_SYNC" | "PENDING" | "OUT_OF_SYNC" | "DISABLED";
    pendingCells: number;
    lastOkAt: string | null;
    lastError: string | null;
    outOfSyncSince: string | null;
  };
  rates: {
    /** rate/restriction cells waiting for the projector */
    dirtyCells: number;
    /** rate/restriction cells the channel manager refused: held, no longer re-sent, their batch reads failed. Send a corrected value for those nights (§6.6) */
    parkedCells: number;
    lastPushAt: string | null;
    lastErrorAt: string | null;
    lastError: string | null;
    /** Nights where the last read of the channel manager found it holding something other than our record (a price or stay rule changed in its own screen or on an OTA extranet). 0 = the last read agreed. The cells are pushed as channel.drift.detected */
    driftCells?: number;
    /** When that read found them; null when nothing differs */
    driftSeenAt?: string | null;
  };
  /** Where this integration stands with the channel shield. Reads and bookings are never affected */
  shield: {
    /** CLEAR nothing held against the integration · WATCH noted, nothing refused · PAUSED only writes that close inventory are accepted · SUSPENDED every write refused until ZimmerStack releases it */
    level: "CLEAR" | "WATCH" | "PAUSED" | "SUSPENDED";
    /** Why, when the level is not CLEAR */
    reason: string | null;
    /** When a pause ends on its own (ISO instant); null = until released, or not paused */
    until: string | null;
  };
  newestPendingBatch: {
    batchId: string;
    resource: "availability" | "rates" | "restrictions";
    createdAt: string;
    requestedCells: number;
    acceptedCells: number;
    noopCells: number;
    rejected: Array<{
      cells: number;
      error: string;
    }>;
    status: "landed" | "pending" | "failed";
    pendingCells: number;
    /** Cells of this batch the channel manager refused: held, not re-sent (§6.6). More than 0 reads failed */
    parkedCells: number;
    lastError: string | null;
    /** Cells written to our record that reach no channel, by room type or rate plan. Not-linked cells are not counted as pending (they are sent nowhere); not-mapped ones are sent and counted like any other */
    unreachable?: Array<{
      /** The room type, on an availability batch */
      roomTypeId?: number;
      /** The rate plan, on a rates or restrictions batch */
      ratePlanId?: number;
      /** How many of the batch's cells are this room type's or plan's */
      cells: number;
      /** not-linked: the room type or plan has no link to the channel manager, so nothing was sent for it (GET /catalog shows its sync state); the batch reads failed. not-mapped: linked and sent, but no connected channel that is switched on sells the plan, by what was last read of the hotel's connections (nightly): nothing sells or stops because of it. A not-mapped plan does not fail the batch */
      status: "not-linked" | "not-mapped";
      message: string;
    }>;
  } | null;
}

export interface BookingCreate {
  /** Your own reservation id; unique per property. A retried POST with the same value returns the same booking while it is live and yours; after a cancel, a new stay needs a new reference (409 EXTERNAL_REFERENCE_REUSED otherwise) */
  externalReference: string;
  /** Hotel-local calendar date, YYYY-MM-DD */
  checkIn: string;
  /** Exclusive: the checkout day is not a night */
  checkOut: string;
  /** ISO 4217; must equal the property's (GET /property) */
  currency: string;
  /** Who booked; found or created in the PMS by phone */
  guest: {
    /** Full name as the guest typed it */
    name: string;
    /** Guest phone, digits with an optional leading + */
    phone: string & string;
    /** Guest email, when you have it; we write to it only if the owner switches our confirmation on */
    email?: string;
    /** Special requests for the desk; shown in the PMS, never sent anywhere */
    notes?: string;
  };
  /** One entry per ROOM; two rooms of the same type are two entries */
  rooms: Array<{
    /** ZimmerStack room type id: roomTypes[].id from GET /catalog, never guessed */
    roomTypeId: number;
    /** Optional: the plan the guest booked, ratePlans[].id from GET /catalog; must belong to roomTypeId. Decides the meal plan; omitted = room only (EP) */
    ratePlanId?: number;
    /** Adults in this room; at most the room type's maxAdults */
    adults: number;
    /** Children in this room; default 0; at most the room type's maxChildren */
    children?: number;
    /** The nightly price YOU charged for this room, MAJOR units (e.g. 4500 or "4500.00"), 1 to 21474836, taxes as you sold them */
    nightlyRate: number | string;
  }>;
  /** How to read nightlyRate at a hotel outside India that has confirmed its tax lines. true (the default): the rate is what the guest paid online; it is split into the hotel's lines and totalAmount does not move, except for a line the hotel collects at the property itself (a city tax per person), which is added and paid at the hotel. false: the rate is as the hotel sells it at its desk; the lines the hotel adds on top are added and totalAmount grows, while lines the hotel keeps inside its prices stay inside. Read totalAmount and taxes in the answer. false is refused with 409 TAXES_NOT_CONFIGURED at a hotel with no confirmed lines (every hotel in India) and with 409 TAXES_INSIDE_RATES at a hotel that adds nothing on top; true, or omitting the field, changes nothing at a hotel with no confirmed lines */
  nightlyRateIncludesTaxes?: boolean;
  /** Omit when nothing was collected; an amount above 0 needs the bookings:payments scope */
  payment?: {
    /** What you collected so far, MAJOR units; 0 = nothing collected (pay at hotel); never more than the stay's total */
    amount: number | string;
    /** How you collected it */
    method: "ONLINE" | "CARD" | "UPI" | "NETBANKING" | "CASH";
    /** Your gateway's payment or transaction id */
    reference?: string;
  };
  /** Booking-level remarks for the desk (promo code, source page) */
  notes?: string;
}

export interface BookingCancel {
  /** Why; kept on the booking's activity log */
  reason?: string;
}

export interface BookingsQuery {
  /** Created on or after this instant (ISO 8601); default: the last 7 days */
  since?: string;
  /** Your own reservation id; unique per property. A retried POST with the same value returns the same booking while it is live and yours; after a cancel, a new stay needs a new reference (409 EXTERNAL_REFERENCE_REUSED otherwise) */
  externalReference?: string;
  /** 1 to 100; default 50 */
  limit?: number;
}

export interface Booking {
  bookingId: number;
  reference: string;
  externalReference: string | null;
  status: "UPCOMING" | "INHOUSE" | "COMPLETED" | "CANCELLED" | "NOSHOW";
  /** Hotel-local calendar date, YYYY-MM-DD */
  checkIn: string;
  /** Hotel-local calendar date, YYYY-MM-DD */
  checkOut: string;
  nights: number;
  currency: string;
  /** MAJOR units, two decimals: the whole stay */
  totalAmount: string;
  /** MAJOR units, two decimals: collected so far */
  totalPaid: string;
  /** MAJOR units, two decimals: owed at the hotel */
  balanceDue: string;
  guest: {
    name: string;
    phone: string;
    email: string | null;
  };
  rooms: Array<{
    bookingRoomId: number;
    roomTypeId: number;
    ratePlanId: number | null;
    mealPlan: "EP" | "CP" | "MAP" | "AP";
    adults: number;
    children: number;
    /** MAJOR units, two decimals */
    nightlyRate: string;
    status: "UPCOMING" | "CHECKEDIN" | "CHECKEDOUT" | "CANCELLED" | "NOSHOW";
  }>;
  inventory: {
    eventRecorded: boolean;
    /** false = this property has no channel manager; nothing is pushed */
    channelManager: boolean;
    pushedBy: "inventory-drain";
  };
  replay: boolean;
  createdAt: string;
  cancelledAt: string | null;
  /** The hotel's own tax lines on this booking. Present only where the hotel has confirmed them (outside India); absent on every other booking */
  taxes?: {
    /** How the nightly rate was read when the booking was made: true = it was split into the lines; false = lines the hotel adds on top were added to the total */
    nightlyRateIncludesTaxes: boolean;
    /** The hotel's own tax lines on this booking, in the order the hotel applies them */
    lines: Array<{
      /** The line's filing code as the hotel set it up (for example TH-VAT) */
      code: string;
      /** The line's name as the hotel's bill prints it */
      name: string;
      /** TAX is owed to an authority; FEE is the hotel's own charge (a service charge); PASS_THROUGH is held for someone else */
      kind: "TAX" | "FEE" | "PASS_THROUGH";
      /** true: inside the nightly rate; false: added on top of it */
      includedInRate: boolean;
      /** MAJOR units, two decimals, for the whole stay; 0.00 when the desk waived the line */
      amount: string;
    }>;
    /** MAJOR units, two decimals: the part of the lines that sits inside the nightly rates */
    includedInRates: string;
    /** MAJOR units, two decimals: the part of the lines added on top; already inside totalAmount */
    addedToTotal: string;
  };
}

