export interface SandboxBooking {
  /** The PMS booking id, the one the webhook carries */
  bookingId: number;
  /** The booking reference, SBX-… — the webhook's booking.reference */
  reference: string;
  /** The pretend channel-side id */
  channelBookingId: string;
  otaName: string;
  /** The stay's state. GET /channel-bookings reads the same booking as status CONFIRMED (or CANCELLED) with stayStatus UPCOMING */
  status: "UPCOMING" | "CANCELLED";
  guestName: string;
  checkIn: string;
  checkOut: string;
  nights: number;
  rooms: number;
  roomTypeId: number;
  /** Major units, per room per night: the average when the nights differ. Each night is priced from the sandbox's own record, what GET /rates gives for the room type's first rate plan */
  nightlyRate: number;
  /** Major units: every night's price × rooms */
  total: number;
  currency: string;
  paidByOta: boolean;
  /** true when a night had no sandbox availability left — the booking lands anyway, as an OTA booking would */
  oversold: boolean;
  createdAt: string;
  /** On a no-show simulation: the stay's own state after it, NOSHOW or UPCOMING. status above stays UPCOMING for a no-show, because the booking is not cancelled */
  stayStatus?: string;
  /** What this call put on the wire for the sandbox's webhook endpoints */
  webhook: {
    eventType: "channel.booking.created" | "channel.booking.modified" | "channel.booking.cancelled" | "direct.booking.created" | "direct.booking.modified" | "direct.booking.cancelled";
    /** The event is in the outbox; every active endpoint on the sandbox receives it within seconds */
    queued: boolean;
  };
}

